package com.infosys.irs.controller;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Controller;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.validation.BindingResult;

@Controller
public class RegistrationController {

    private static final Logger logger = LoggerFactory.getLogger(RegistrationController.class);

    @PostMapping(value = "registerUser")
    public ModelAndView addCustomer(@Valid @ModelAttribute("command") User user, BindingResult result) {
        ModelAndView modelAndView = new ModelAndView();
        if (result.hasErrors()) {
            modelAndView.addObject("message", "Validation Failed!");
        } else {
            try {
                registrationService.registerUser(user);
                modelAndView.addObject("successMessage", "Registration Successful!");
            } catch (UserIdAlreadyPresentException e) {
                logger.error("Error in user registration", e);
                modelAndView.addObject("message", "User ID already exists");
            }
        }
        return modelAndView;
    }
}

package com.infosys.irs.utility;

import org.aspectj.lang.annotation.AfterThrowing;
import org.aspectj.lang.annotation.Aspect;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

@Component
@Aspect
public class LoggingAspect {

    private static final Logger logger = LoggerFactory.getLogger(LoggingAspect.class);

    @AfterThrowing(pointcut = "execution(* com.infosys.irs.repository.*.*(..))", throwing = "exception")
    public void logExceptionFromRepository(Exception exception) {
        logger.error("Repository exception: ", exception);
    }

    @AfterThrowing(pointcut = "execution(* com.infosys.irs.service.*.*(..))", throwing = "exception")
    public void logExceptionFromService(Exception exception) {
        if (exception.getMessage().contains("Service")) {
            logger.error("Service exception: ", exception);
        }
    }
}

